begin;
set local search_path=public,extensions;
select no_plan();
insert into auth.users(id,email)values('f1000000-0000-4000-8000-000000000001','checkout-owner@qa.invalid'),('f1000000-0000-4000-8000-000000000002','checkout-other@qa.invalid');
insert into public.tenants(id,name,slug)values('f2000000-0000-4000-8000-000000000001','Checkout QA','checkout-qa');
insert into public.tenant_memberships(tenant_id,user_id,role)values('f2000000-0000-4000-8000-000000000001','f1000000-0000-4000-8000-000000000001','owner');
insert into public.properties(id,tenant_id,name,property_type,timezone)values('f3000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','Checkout QA','hotel','Pacific/Auckland');
select set_config('qa.day',(now()at time zone'Pacific/Auckland')::date::text,true);
insert into public.accommodation_types(id,tenant_id,property_id,name,kind,max_occupancy,base_rate)values('f4000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','Checkout room','room',2,0);
insert into public.accommodation_units(id,tenant_id,property_id,type_id,name,housekeeping_status)select ('f5000000-0000-4000-8000-00000000000'||n)::uuid,'f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f4000000-0000-4000-8000-000000000001','QA'||n,'clean'from generate_series(1,2)n;
insert into public.guests(id,tenant_id,full_name)values('f6000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','Checkout guest');
insert into public.reservations(id,tenant_id,property_id,guest_id,status,check_in,check_out,total_amount,currency)select ('f7000000-0000-4000-8000-00000000000'||n)::uuid,'f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','f6000000-0000-4000-8000-000000000001','checked_in',current_setting('qa.day')::date-case when n=1 then 1 else 0 end,current_setting('qa.day')::date+2,0,'NZD'from generate_series(1,2)n;
insert into public.unit_holds(tenant_id,property_id,unit_id,kind,reservation_id,during)select r.tenant_id,r.property_id,('f5000000-0000-4000-8000-00000000000'||n)::uuid,'reservation',r.id,daterange(r.check_in,r.check_out,'[)')from generate_series(1,2)n join public.reservations r on r.id=('f7000000-0000-4000-8000-00000000000'||n)::uuid;

update public.guests set phone='+919999990001'where id='f6000000-0000-4000-8000-000000000001';
insert into public.whatsapp_connections(id,tenant_id,property_id,phone_number_id,waba_id,credentials_ref)values('f8000000-0000-4000-8000-000000000001','f2000000-0000-4000-8000-000000000001','f3000000-0000-4000-8000-000000000001','checkout-qa-sender','checkout-qa-waba','fixture-no-token');
set local role service_role;
select public.sync_whatsapp_provider_templates('f8000000-0000-4000-8000-000000000001','checkout-qa-waba','[{"provider_id":"checkout-room-qa","name":"checkout_room_qa","language":"en_US","category":"utility","provider_status":"APPROVED","body":"Your stay in {{room_name}} is complete. Thank you.","parameter_names":["room_name"],"supported":true,"definition":{"components":[{"type":"BODY","text":"Your stay in {{room_name}} is complete. Thank you."}]}}]');
reset role;set local role authenticated;
select set_config('request.jwt.claims','{"sub":"f1000000-0000-4000-8000-000000000001","role":"authenticated"}',true);
select public.save_whatsapp_automation_rule('f3000000-0000-4000-8000-000000000001','checked_out',0,true,(select id from public.message_templates where property_id='f3000000-0000-4000-8000-000000000001'and name='checkout_room_qa'),'["room_name"]',0);
select public.authorize_whatsapp_stay_updates('f3000000-0000-4000-8000-000000000001','f7000000-0000-4000-8000-000000000002',0,'granted','Local QA proof: synthetic guest and phone verified.',true);
select public.check_out_reservation('f7000000-0000-4000-8000-000000000002');
reset role;
select is(private.whatsapp_reservation_room_name('f7000000-0000-4000-8000-000000000002'),'QA2','released room remains available to historical message rendering');
select is((select payload->>'room_name'from public.whatsapp_automation_events where reservation_id='f7000000-0000-4000-8000-000000000002'and event_key='checked_out'),'QA2','checkout domain event captures original room name');
set local role service_role;
select is(public.dispatch_whatsapp_automations(50,'https://guest.qa.example'),1,'checkout automation queues after same-day inventory release');
reset role;
select is((select body from public.messages where automation_event_id=(select id from public.whatsapp_automation_events where reservation_id='f7000000-0000-4000-8000-000000000002'and event_key='checked_out')),'Your stay in QA2 is complete. Thank you.','guest receives the departed room in the rendered template');
select is((select count(*)::int from public.unit_holds where reservation_id='f7000000-0000-4000-8000-000000000002'and active),0,'historical rendering does not restore inventory hold');
set local role authenticated;
select throws_ok($$select private.whatsapp_reservation_room_name('f7000000-0000-4000-8000-000000000002')$$,'42501',null,'private room lookup is not exposed to hotel clients');
select *from finish();rollback;
